function Load-Pixels($path) {
    $uri = New-Object System.Uri $path
    $frame = [System.Windows.Media.Imaging.BitmapFrame]::Create(
        $uri,
        [System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat,
        [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
    $conv = New-Object System.Windows.Media.Imaging.FormatConvertedBitmap
    $conv.BeginInit()
    $conv.Source = $frame
    $conv.DestinationFormat = [System.Windows.Media.PixelFormats]::Bgra32
    $conv.EndInit()
    $w = $conv.PixelWidth; $h = $conv.PixelHeight
    $stride = $w * 4
    $buf = New-Object byte[] ($stride * $h)
    $conv.CopyPixels($buf, $stride, 0)
    return @{ W = $w; H = $h; Stride = $stride; Buf = $buf; Src = $conv }
}

function BBox($img, $marginLum) {
    $W = $img.W; $H = $img.H; $s = $img.Stride; $b = $img.Buf
    # background = average of the four corners
    $corners = @(@(4,4), @($W-5,4), @(4,$H-5), @($W-5,$H-5))
    $bg = 0.0
    foreach ($c in $corners) {
        $i = $c[1]*$s + $c[0]*4
        $bg += (0.299*$b[$i+2] + 0.587*$b[$i+1] + 0.114*$b[$i])
    }
    $bg = $bg / 4.0
    $th = $bg + $marginLum
    $minX = $W; $maxX = 0; $minY = $H; $maxY = 0
    for ($y = 0; $y -lt $H; $y++) {
        $row = $y * $s
        for ($x = 0; $x -lt $W; $x++) {
            $i = $row + $x*4
            $l = 0.299*$b[$i+2] + 0.587*$b[$i+1] + 0.114*$b[$i]
            if ([math]::Abs($l - $bg) -gt $marginLum) {
                if ($x -lt $minX) { $minX = $x }
                if ($x -gt $maxX) { $maxX = $x }
                if ($y -lt $minY) { $minY = $y }
                if ($y -gt $maxY) { $maxY = $y }
            }
        }
    }
    return @{ BG = $bg; MinX = $minX; MaxX = $maxX; MinY = $minY; MaxY = $maxY;
              W = ($maxX-$minX+1); H = ($maxY-$minY+1) }
}

function Save-Crop($img, $bb, $outW, $outH, $path) {
    $crop = New-Object System.Windows.Media.Imaging.CroppedBitmap(
        $img.Src,
        (New-Object System.Windows.Int32Rect $bb.MinX, $bb.MinY, $bb.W, $bb.H))
    $tb = New-Object System.Windows.Media.Imaging.TransformedBitmap(
        $crop,
        (New-Object System.Windows.Media.ScaleTransform ($outW / [double]$bb.W), ($outH / [double]$bb.H)))
    $enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
    $enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($tb))
    $fs = [System.IO.File]::Create($path)
    $enc.Save($fs); $fs.Close()
    Write-Host "  saved $path  ($outW x $outH)"
}

