Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase

function CornerScan($path, $label) {
    $frame = [System.Windows.Media.Imaging.BitmapFrame]::Create(
        (New-Object System.Uri $path),
        [System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat,
        [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
    $conv = New-Object System.Windows.Media.Imaging.FormatConvertedBitmap
    $conv.BeginInit(); $conv.Source = $frame
    $conv.DestinationFormat = [System.Windows.Media.PixelFormats]::Bgra32
    $conv.EndInit()

    $w = $conv.PixelWidth; $h = $conv.PixelHeight
    $stride = $w * 4
    $buf = New-Object byte[] ($stride * $h)
    $conv.CopyPixels($buf, $stride, 0)

    # reference tone from a quiet spot just above the corner band
    $ri = ([int]($h * 0.60)) * $stride + ([int]($w * 0.02)) * 4
    $ref = 0.299*$buf[$ri+2] + 0.587*$buf[$ri+1] + 0.114*$buf[$ri]

    $x0 = 0; $x1 = [int]($w * 0.30)
    $y0 = [int]($h * 0.86); $y1 = $h - 1

    $count = 0; $minX = $w; $maxX = 0; $minY = $h; $maxY = 0
    for ($y = $y0; $y -le $y1; $y++) {
        $row = $y * $stride
        for ($x = $x0; $x -le $x1; $x++) {
            $i = $row + $x * 4
            $l = 0.299*$buf[$i+2] + 0.587*$buf[$i+1] + 0.114*$buf[$i]
            if ([math]::Abs($l - $ref) -gt 9) {
                $count++
                if ($x -lt $minX) { $minX = $x }
                if ($x -gt $maxX) { $maxX = $x }
                if ($y -lt $minY) { $minY = $y }
                if ($y -gt $maxY) { $maxY = $y }
            }
        }
    }
    if ($count -eq 0) {
        Write-Host ("  {0,-20} corner clean (ref lum {1})" -f $label, [math]::Round($ref,1))
    } else {
        Write-Host ("  {0,-20} {1} odd pixels in bottom-left  bbox x {2}..{3} y {4}..{5}  (ref lum {6})" -f `
            $label, $count, $minX, $maxX, $minY, $maxY, [math]::Round($ref,1))
    }
}

